	t.Parallel()

	privateKey := testPrivateKey()
	for name, payload := range map[string][]byte{
		"duplicate member": []byte(`{"name":"first","name":"second"}`),
		"invalid UTF-8":    {'{', '"', 'x', '"', ':', '"', 0xff, '"', '}'},
		"not an object":    []byte(`null`),
