// quiescePendingCommands keeps each unreaped leader until its entire owned
// process group is confirmed stopped. Callers must preserve resources on error.
func quiescePendingCommands(pending *[]*Process) []string {
	retained := []*Process{}
	errs := []string{}
	for _, process := range *pending {
		if !process.Reaped {
			if e := process.Stop(5*time.Second, true); e != nil {
				retained = append(retained, process)
				errs = append(errs, fmt.Sprintf("pending qualification command %d is not confirmed stopped: %v", process.PID(), e))
			}
		}
	}
	*pending = retained
	return errs
}

func nativeProduction(t *testing.T) *ProductionQualification {
	t.Helper()
	q, e := NewProductionQualification(t.Context(), ProductionOptions{})
	if e != nil {
		t.Fatal(e)
	}
	t.Cleanup(func() { _ = os.RemoveAll(q.Root) })
	return q
}

func NewProductionQualification(ctx context.Context, o ProductionOptions) (*ProductionQualification, error) {
	root, e := os.MkdirTemp("/tmp", "tspr-")
	if e != nil {
		return nil, e
	}
	if e = os.Chmod(root, 0o700); e != nil {
		return nil, e
	}
	suffix := tail(filepath.Base(root), 4)
	q := &ProductionQualification{Ctx: ctx, Options: o, Command: Execute, Root: root, Bridge: "tspr" + suffix, Table: "tspr_" + suffix, Taps: map[string]string{}, VMs: map[string]*ProductionVM{}, AuditPath: filepath.Join(root, "oci-audit.json"), Report: Object{"result": "incomplete", "artifacts": Object{}}}
	for i, slot := range ProductionSlots {
		q.Taps[slot] = fmt.Sprintf("tsp%s%d", suffix, i+1)
	}
	return q, nil
}
func (q *ProductionQualification) command(args []string, o CommandOptions) (CommandResult, error) {
	r, e := q.Command(q.Ctx, args, o)
	if pending, ok := errors.AsType[*PendingCommandError](e); ok && !slices.Contains(q.PendingCommands, pending.Process) {
		q.PendingCommands = append(q.PendingCommands, pending.Process)
	}
	return r, e
}

func (l *Lab) Cleanup(preserve bool) []string {
	l.defaults()
	originalContext := l.Ctx
	l.Ctx = context.WithoutCancel(originalContext)
	defer func() { l.Ctx = originalContext }()
	errs := []string{}
	if pendingErrors := quiescePendingCommands(&l.PendingCommands); len(pendingErrors) > 0 {
		l.Note("guest_images_retained", Object{"path": l.Images, "reason": "pending_command_cleanup_failed"})
		return pendingErrors
	}
	imagesSafe := true
	stop := func(p **Process, label string) {
		if *p == nil {
			return
		}
		if e := (*p).Stop(5*time.Second, false); e != nil {
			errs = append(errs, fmt.Sprintf("stop %s: %v", label, e))
			return
		}
		*p = nil
	}
	stop(&l.SessionProbeProcess, "session probe")
	if e := l.RemoveNTPFirewallRule(); e != nil {
		errs = append(errs, "remove owned private NTP firewall rule: "+e.Error())
	}
	if len(l.PendingCommands) > 0 {
		return errs
	}
	for i := len(l.CreatedNFTTables) - 1; i >= 0; i-- {
		table := l.CreatedNFTTables[i]
		r, e := l.sudoAllow("nft", "delete", "table", "bridge", table)
		if len(l.PendingCommands) > 0 {
			return append(errs, fmt.Sprintf("delete owned nft table %s is not confirmed stopped: %v", table, e))
		}
		if e != nil || r.Code != 0 {
			errs = append(errs, fmt.Sprintf("delete owned nft table %s: %v %s", table, e, r.Stderr))
		} else {
			l.CreatedNFTTables = slices.Delete(l.CreatedNFTTables, i, i+1)
		}
	}
	for i := len(Guests) - 1; i >= 0; i-- {
		if v := l.VMs[Guests[i]]; v != nil {
			if e := v.Stop(); e != nil {
				imagesSafe = false
				errs = append(errs, fmt.Sprintf("stop %s: %v", v.Name, e))
			}
		}
	}
	if l.SocketDir != "" {
		errs = append(errs, CleanupOwnedSockets(l.VMs, l.SocketDir)...)
	}
	for i := len(l.Mounted) - 1; i >= 0; i-- {
		mount := l.Mounted[i]
		r, e := l.sudoAllow("umount", mount)
		if len(l.PendingCommands) > 0 {
			return append(errs, fmt.Sprintf("unmount %s is not confirmed stopped: %v", mount, e))
		}
		if e != nil || r.Code != 0 {
			errs = append(errs, fmt.Sprintf("unmount %s: %v %s", mount, e, r.Stderr))
		} else {
			l.Mounted = slices.Delete(l.Mounted, i, i+1)
		}
	}
	stop(&l.ChronyProcess, "chrony")
	if l.ChronyControlDir != "" && l.ChronyProcess == nil {
		r, e := l.sudoAllow("rm", "-f", "--", filepath.Join(l.ChronyControlDir, "chronyd.sock"))
		if len(l.PendingCommands) > 0 {
			return append(errs, fmt.Sprintf("Chrony socket removal is not confirmed stopped: %v", e))
		}
		if e == nil && r.Code == 0 {
			r, e = l.sudoAllow("rmdir", "--", l.ChronyControlDir)
			if len(l.PendingCommands) > 0 {
				return append(errs, fmt.Sprintf("Chrony directory removal is not confirmed stopped: %v", e))
			}
		}
		if e != nil || r.Code != 0 {
			errs = append(errs, fmt.Sprintf("remove owned Chrony control directory %s: %v %s", l.ChronyControlDir, e, r.Stderr))
		} else {
			l.ChronyControlDir = ""
		}
	}
	for i := len(l.CreatedLinks) - 1; i >= 0; i-- {
		link := l.CreatedLinks[i]
		r, e := l.sudoAllow("ip", "link", "del", link)
		if len(l.PendingCommands) > 0 {
			return append(errs, fmt.Sprintf("delete link %s is not confirmed stopped: %v", link, e))
		}
		if e != nil || r.Code != 0 {
			errs = append(errs, fmt.Sprintf("delete link %s: %v %s", link, e, r.Stderr))
		} else {
			l.CreatedLinks = slices.Delete(l.CreatedLinks, i, i+1)
		}
	}
	if preserve || len(errs) > 0 {
		reason := "qualification_failed"
		if !preserve {
			reason = "cleanup_failed"
		}
		l.Note("guest_images_retained", Object{"path": l.Images, "reason": reason})
	} else if imagesSafe && len(l.Mounted) == 0 {
		_ = os.RemoveAll(l.Images)
	} else {
		errs = append(errs, "guest images retained for manual cleanup: "+l.Images)
	}
	_ = os.RemoveAll(l.Secrets)
	_ = os.RemoveAll(l.Stage)
	return errs
}

func (q *ProductionQualification) Cleanup() []string {
	originalContext := q.Ctx
	q.Ctx = context.WithoutCancel(originalContext)
	defer func() { q.Ctx = originalContext }()
	failures := []string{}
	if pendingErrors := quiescePendingCommands(&q.PendingCommands); len(pendingErrors) > 0 {
		return pendingErrors
	}
	for _, slot := range ProductionSlots {
		if vm := q.VMs[slot]; vm != nil {
			if e := vm.Stop(); e != nil {
				failures = append(failures, fmt.Sprintf("stop %s: %v", slot, e))
			}
		}
	}
	if q.Simulator != nil {
		done, e := q.Simulator.Exited()
		if e == nil && !done {
			_, e = q.Simulator.WaitUnreaped(0)
			id, groupErr := q.Simulator.Group()
			if groupErr != nil {
				e = groupErr
			} else {
				e = q.Simulator.signalGroup(id, syscall.SIGTERM)
			}
			if e != nil && !errors.Is(e, syscall.ESRCH) {
				failures = append(failures, "signal simulator: "+e.Error())
			}
			done, e = q.Simulator.WaitUnreaped(20 * time.Second)
			if e == nil && !done {
				failures = append(failures, "simulator required SIGKILL during cleanup")
			}
		}
		if e == nil {
			e = q.Simulator.Stop(10*time.Second, true)
		}
		if e != nil {
			failures = append(failures, "stop simulator: "+e.Error())
		} else {
			q.Simulator = nil
		}
	}
	if q.NTP != nil {
		q.NTP.Close()
		for k, v := range q.NTP.Snapshot() {
			q.Report[k] = v
		}
		q.NTP = nil
	}
	for i := len(q.Mounted) - 1; i >= 0; i-- {
		mount := q.Mounted[i]
		if _, e := q.command([]string{"umount", mount}, CommandOptions{}); e != nil {
			failures = append(failures, "unmount "+mount+": "+e.Error())
		} else {
			q.Mounted = slices.Delete(q.Mounted, i, i+1)
		}
		if len(q.PendingCommands) > 0 {
			return failures
		}
	}
	for i := len(q.CreatedTables) - 1; i >= 0; i-- {
		family, name := q.CreatedTables[i][0], q.CreatedTables[i][1]
		r, e := q.command([]string{"nft", "list", "table", family, name}, CommandOptions{})
		if len(q.PendingCommands) > 0 {
			return append(failures, fmt.Sprintf("firewall counter capture is not confirmed stopped: %v", e))
		}
		if e != nil {
			failures = append(failures, "capture "+family+" firewall counters: "+e.Error())
		} else {
			filename := "firewall-" + family + ".txt"
			if e = os.WriteFile(filepath.Join(q.Root, filename), []byte(r.Stdout), 0o600); e != nil {
				failures = append(failures, e.Error())
			}
			if q.Report["firewallCounterFiles"] == nil {
				q.Report["firewallCounterFiles"] = Object{}
			}
			object(q.Report["firewallCounterFiles"])[family] = filename
			q.Report["firewallDrops"] = integer(q.Report["firewallDrops"]) + droppedPackets(r.Stdout)
		}
		if _, e = q.command([]string{"nft", "delete", "table", family, name}, CommandOptions{}); e != nil {
			failures = append(failures, "delete "+family+" "+name+": "+e.Error())
		} else {
			q.CreatedTables = slices.Delete(q.CreatedTables, i, i+1)
		}
		if len(q.PendingCommands) > 0 {
			return failures
		}
	}
	for i := len(q.CreatedLinks) - 1; i >= 0; i-- {
		link := q.CreatedLinks[i]
		if _, e := q.command([]string{"ip", "link", "delete", link}, CommandOptions{}); e != nil {
			failures = append(failures, "delete "+link+": "+e.Error())
		} else {
			q.CreatedLinks = slices.Delete(q.CreatedLinks, i, i+1)
		}
		if len(q.PendingCommands) > 0 {
			return failures
		}
	}
	stopped := true
	for _, vm := range q.VMs {
		if vm.Process != nil {
			stopped = false
		}
	}
	if q.Options.Run && stopped && len(q.Mounted) == 0 {
		for _, slot := range ProductionSlots {
			if e := removeMissing(filepath.Join(q.Root, slot+".ext4")); e != nil {
				failures = append(failures, e.Error())
			}
		}
	}
	return failures
}

