func (l *Lab) CaptureHostStatus(label string) {
	l.defaults()
	if l.HostDiagnostics[label] {
		return
	}
	l.HostDiagnostics[label] = true
	captured := l.Now()
	snapshot := Object{"captured_at": captured, "label": label}
	r, e := l.cmd([]string{l.Binary, "operator", "hosts", "--config", l.OperatorConfig}, CommandOptions{Timeout: 10 * time.Second, AllowFailure: true})
	if errors.Is(e, contextDeadline) {
		snapshot["status"] = "timeout"
	} else if e != nil {
		snapshot["status"] = "error"
		snapshot["error_type"] = fmt.Sprintf("%T", e)
	} else if r.Code != 0 {
		snapshot["status"] = "operator_failed"
		snapshot["exit_code"] = r.Code
	} else {
		v, e := decode(r.Stdout)
		hosts, ce := CuratedHostStatuses(v, captured)
		if e != nil || ce != nil {
			snapshot["status"] = "error"
		} else {
			snapshot["status"] = "ok"
			snapshot["hosts"] = hosts
		}
	}
	path := filepath.Join(l.Logs, "host-status-"+label+".json")
	if e = writeJSON(path, snapshot); e != nil {
		l.Note("host_status_diagnostics", Object{"label": label, "status": "write_failed", "error_type": fmt.Sprintf("%T", e)})
		return
	}
	l.Note("host_status_diagnostics", Object{"label": label, "path": path, "status": snapshot["status"]})
}
func (l *Lab) CaptureClusterDiagnostics() {
	if l.ClusterCaptured {
		return
	}
	l.ClusterCaptured = true
	l.CaptureHostStatus("early-pending")
	for _, name := range Controllers {
		v := l.VMs[name]
		if v == nil || v.Process == nil {
			continue
		}
		done, e := v.Process.Exited()
		if e != nil || done {
			continue
		}
		r, e := l.SSH(name, "systemctl status ts-orch.service --no-pager --full; journalctl -u ts-orch.service -b --no-pager -n 300 -o short-iso-precise; ps -eo pid,ppid,stat,etime,cmd | grep '[t]errascale-orchestrator'", 12*time.Second, true)
		path := filepath.Join(l.Logs, name+"-live-diagnostics.txt")
		text := r.Stdout + r.Stderr
		if e != nil {
			text = fmt.Sprintf("controller diagnostics unavailable: %v\n", e)
		}
		_ = os.WriteFile(path, []byte(text), 0o600)
		l.Note("cluster_diagnostics", Object{"name": name, "path": path, "exit_code": r.Code})
	}
	if _, e := os.Stat(l.NATSDiag); e != nil {
		return
	}
	if _, e := os.Stat(filepath.Join(l.Secrets, "c1.creds")); e != nil {
		return
	}
	urls := []string{}
	for _, name := range Controllers {
		urls = append(urls, "tls://"+l.Addresses[name]+":4222")
	}
	argv := []string{l.NATSDiag, "--creds", filepath.Join(l.Secrets, "c1.creds"), "--operator-creds", filepath.Join(l.Secrets, "natsdiag.creds"), "--cell", "lab", "--urls", strings.Join(urls, ","), "--ca", filepath.Join(l.Secrets, "nats-ca.pem"), "--cert", filepath.Join(l.Secrets, "nats-c1.pem"), "--key", filepath.Join(l.Secrets, "nats-c1.key"), "--operator-cert", filepath.Join(l.Secrets, "nats-operator.pem"), "--operator-key", filepath.Join(l.Secrets, "nats-operator.key")}
	if l.ActiveOperationID != "" {
		argv = append(argv, "--operation-id", l.ActiveOperationID)
	}
	r, e := l.cmd(argv, CommandOptions{Timeout: 35 * time.Second, AllowFailure: true})
	path := filepath.Join(l.Logs, "nats-live-diagnostics.jsonl")
	text := r.Stdout + r.Stderr
	if e != nil {
		text = fmt.Sprintf("NATS diagnostics unavailable: %v\n", e)
	}
	_ = os.WriteFile(path, []byte(text), 0o600)
	l.Note("cluster_diagnostics", Object{"name": "nats", "path": path, "exit_code": r.Code})
}

func CuratedHostStatuses(statuses any, captured time.Time) ([]Object, error) {
	rows, ok := statuses.([]any)
	if !ok {
		return nil, errors.New("operator hosts did not return a list")
	}
	result := []Object{}
	for _, raw := range rows {
		s, ok := raw.(map[string]any)
		if !ok {
			return nil, errors.New("operator hosts returned an invalid status")
		}
		r, ok := s["registration"].(map[string]any)
		if !ok {
			return nil, errors.New("operator hosts returned an invalid status")
		}
		expiry, _ := time.Parse(time.RFC3339Nano, str(s["session_expires_at"]))
		capacity := object(r["capacity"])
		reports := []Object{}
		for _, rawReport := range array(s["reports"]) {
			report, ok := rawReport.(map[string]any)
			if !ok {
				continue
			}
			var h any
			if id, ok := report["session_id"].(string); ok {
				h = head(hashBytes([]byte(id)), 32)
			}
			reports = append(reports, Object{"role": report["role"], "generation": report["generation"], "state": report["state"], "digest_prefix": head(str(report["digest"]), 12), "epoch": report["epoch"], "observed_at": report["observed_at"], "session_id_hash": h})
		}
		result = append(result, Object{"node": r["node"], "environment": r["environment"], "roles": r["roles"], "registration_generation": r["generation"], "capacity": Object{"cpu": capacity["cpu"], "memory_bytes": capacity["memory_bytes"], "disk_bytes": capacity["disk_bytes"]}, "session_expires_at": s["session_expires_at"], "session_current": expiry.After(captured), "verified": s["verified"], "reports": reports})
	}
	return result, nil
}

firewall.text:
func (l *Lab) gateway() string { return l.Subnet.Addr().Next().String() }
func (l *Lab) inputFirewallRules() ([]Object, error) {
	r, e := l.sudo("nft", "-j", "-a", "list", "chain", "ip", "filter", "INPUT")
	if e != nil {
		return nil, e
	}
	v, e := decode(r.Stdout)
	if e != nil {
		return nil, e
	}
	chains := []Object{}
	rules := []Object{}
	for _, entry := range array(object(v)["nftables"]) {
		entry := object(entry)
		if c, ok := entry["chain"]; ok {
			chains = append(chains, object(c))
		}
		if r, ok := entry["rule"]; ok {
			rules = append(rules, object(r))
		}
	}
	if len(chains) != 1 || chains[0]["family"] != "ip" || chains[0]["table"] != "filter" || chains[0]["name"] != "INPUT" || chains[0]["type"] != "filter" || chains[0]["hook"] != "input" {
		return nil, errors.New("host IPv4 filter INPUT is not the active input hook")
	}
	return rules, nil
}
func (l *Lab) ownedNTPRules() ([]Object, error) {
	if l.NTPRuleComment == "" {
		return []Object{}, nil
	}
	rules, e := l.inputFirewallRules()
	if e != nil {
		return nil, e
	}
	return slices.DeleteFunc(rules, func(r Object) bool {
		return r["family"] != "ip" || r["table"] != "filter" || r["chain"] != "INPUT" || r["comment"] != l.NTPRuleComment
	}), nil
}
func jsonEqual(a, b any) bool {
	x, e := json.Marshal(a, json.Deterministic(true))
	if e != nil {
		return false
	}
	y, e := json.Marshal(b, json.Deterministic(true))
	return e == nil && string(x) == string(y)
}
func (l *Lab) ExactNTPRule(rule Object) bool {
	expected := [][2]any{{Object{"meta": Object{"key": "iifname"}}, l.Bridge}, {Object{"payload": Object{"protocol": "ip", "field": "saddr"}}, Object{"prefix": Object{"addr": l.Subnet.Addr().String(), "len": 24}}}, {Object{"payload": Object{"protocol": "ip", "field": "daddr"}}, l.gateway()}, {Object{"payload": Object{"protocol": "udp", "field": "dport"}}, 123}}
	expr := array(rule["expr"])
	if len(expr) != 6 {
		return false
	}
	for i, w := range expected {
		m := object(object(expr[i])["match"])
		if m["op"] != "==" || !jsonEqual(m["left"], w[0]) || !jsonEqual(m["right"], w[1]) {
			return false
		}
	}
	counter, accept := object(expr[4]), object(expr[5])
	_, hasCounter := counter["counter"]
	_, hasAccept := accept["accept"]
	return len(counter) == 1 && len(accept) == 1 && hasCounter && hasAccept
}
func (l *Lab) InstallNTPFirewallRule() error {
	if l.NTPRuleComment != "" {
		return errors.New("private NTP firewall rule was already attempted")
	}
	if !regexp.MustCompile(`^tsf[0-9a-f]{6}b$`).MatchString(l.Bridge) || l.Subnet.Bits() != 24 || !netip.MustParsePrefix("198.19.0.0/16").Contains(l.Subnet.Addr()) {
		return errors.New("private NTP firewall rule requires the owned bridge and /24")
	}
	rules, e := l.inputFirewallRules()
	if e != nil {
		return e
	}
	jump := false
	for _, r := range rules {
		for _, expr := range array(r["expr"]) {
			if object(object(expr)["jump"])["target"] == "nixos-fw" {
				jump = true
			}
		}
	}
	if !jump {
		return errors.New("host INPUT does not route through the expected NixOS firewall")
	}
	l.NTPRuleComment = "ts-orch-fc-ntp-" + token(12)
	if _, e = l.sudo("nft", "insert", "rule", "ip", "filter", "INPUT", "iifname", l.Bridge, "ip", "saddr", l.Subnet.String(), "ip", "daddr", l.gateway(), "udp", "dport", "123", "counter", "accept", "comment", l.NTPRuleComment); e != nil {
		return e
	}
	owned, e := l.ownedNTPRules()
	if e != nil {
		return e
	}
	if len(owned) != 1 || !l.ExactNTPRule(owned[0]) || integer(owned[0]["handle"]) < 1 {
		return errors.New("cannot identify the private NTP firewall rule after insertion")
	}
	l.NTPRuleHandle = integer(owned[0]["handle"])
	l.Note("ntp_firewall_rule", Object{"bridge": l.Bridge, "source": l.Subnet.String(), "destination": l.gateway(), "protocol": "udp", "port": 123, "comment": l.NTPRuleComment, "handle": l.NTPRuleHandle})
	return nil
}
func (l *Lab) RemoveNTPFirewallRule() error {
	if l.NTPRuleComment == "" {
		return nil
	}
	owned, e := l.ownedNTPRules()
	if e != nil {
		return e
	}
	if len(owned) > 1 {
		return errors.New("private NTP firewall comment matched multiple rules")
	}
	if len(owned) == 0 {
		l.NTPRuleComment = ""
		l.NTPRuleHandle = 0
		return nil
	}
	if !l.ExactNTPRule(owned[0]) {
		return errors.New("private NTP firewall rule scope changed")
	}
	handle := integer(owned[0]["handle"])
	if handle < 1 || (l.NTPRuleHandle != 0 && handle != l.NTPRuleHandle) {
		return errors.New("private NTP firewall handle changed")
	}
	if _, e = l.sudo("nft", "delete", "rule", "ip", "filter", "INPUT", "handle", strconv.FormatInt(handle, 10)); e != nil {
		return e
	}
	owned, e = l.ownedNTPRules()
	if e != nil {
		return e
	}
	if len(owned) > 0 {
		return errors.New("private NTP firewall rule remains after deletion")
	}
	l.Note("ntp_firewall_rule_removed", Object{"comment": l.NTPRuleComment, "handle": handle})
	l.NTPRuleComment = ""
	l.NTPRuleHandle = 0
	return nil
}

func ntpRule(comment, destination string) Object {
	match := func(left, right any) Object { return Object{"match": Object{"op": "==", "left": left, "right": right}} }
	payload := func(protocol, field string) Object {
		return Object{"payload": Object{"protocol": protocol, "field": field}}
	}
	return Object{"family": "ip", "table": "filter", "chain": "INPUT", "handle": 101, "comment": comment, "expr": []any{
		match(Object{"meta": Object{"key": "iifname"}}, "tsfabc123b"),
		match(payload("ip", "saddr"), Object{"prefix": Object{"addr": "198.19.7.0", "len": 24}}),
		match(payload("ip", "daddr"), destination), match(payload("udp", "dport"), 123),
		Object{"counter": Object{"packets": 3, "bytes": 228}}, Object{"accept": nil},
	}}
}
func ntpChain(hook string, jump bool) []any {
	entries := []any{Object{"chain": Object{"family": "ip", "table": "filter", "name": "INPUT", "type": "filter", "hook": hook}}}
	if jump {
		entries = append(entries, Object{"rule": Object{"family": "ip", "table": "filter", "chain": "INPUT", "handle": 17, "expr": []any{Object{"jump": Object{"target": "nixos-fw"}}}}})
	}
	return entries
}
